def func(self, global_state):
    instr = global_state.get_current_instruction()
    environment = global_state.environment
    memory_out_size, memory_out_offset = global_state.mstate.stack[-7:-5]
    try:
        callee_address, callee_account, call_data, value, gas, memory_out_offset, memory_out_size = get_call_parameters(global_state, self.dynamic_loader, True)
        if callee_account is not None and callee_account.code.bytecode == '':
            log.debug('The call is related to ether transfer between accounts')
            sender = environment.active_account.address
            receiver = callee_account.address
            transfer_ether(global_state, sender, receiver, value)
            self._write_symbolic_returndata(global_state, memory_out_offset, memory_out_size)
            global_state.mstate.stack.append(global_state.new_bitvec('retval_' + str(instr['address']), 256))
            return [global_state]
    except ValueError as e:
        log.debug('Could not determine required parameters for call, putting fresh symbol on the stack. \n{}'.format(e))
        self._write_symbolic_returndata(global_state, memory_out_offset, memory_out_size)
        global_state.mstate.stack.append(global_state.new_bitvec('retval_' + str(instr['address']), 256))
        return [global_state]
    if environment.static:
        if isinstance(value, int) and value > 0:
            raise WriteProtection('Cannot call with non zero value in a static call')
        if isinstance(value, BitVec):
            if value.symbolic:
                global_state.world_state.constraints.append(value == symbol_factory.BitVecVal(0, 256))
            elif value.value > 0:
                raise WriteProtection('Cannot call with non zero value in a static call')
    native_result = native_call(global_state, callee_address, call_data, memory_out_offset, memory_out_size)
    if native_result:
        return native_result
    transaction = MessageCallTransaction(world_state=global_state.world_state, gas_price=environment.gasprice, gas_limit=gas, origin=environment.origin, caller=environment.active_account.address, callee_account=callee_account, call_data=call_data, call_value=value, static=environment.static)
    raise TransactionStartSignal(transaction, self.op_code, global_state)

