                    headers_ = [{'Location': f'{get_hydrus_server_url()}{get_api_name()}/{path}/{object_id}'}]
                    if len(incomplete_objects) > 0:
                        status = HydraStatus(code=202, title='Object(s) missing required property')
                        response = status.generate()
                        response['objects'] = incomplete_objects
                        return set_response_headers(jsonify(response), headers=headers_, status_code=status.code)
                    else:
                        path_url = f'{get_hydrus_server_url()}{get_api_name()}/{path}'
                        response_url_list = get_iri_from_int_list(path_url, object_id)
                        status_description = f'Objects with ID {object_id} successfully added'
