                        status_response = status.generate()
                        status_response['iri'] = response_url_list
                        return set_response_headers(jsonify(status_response), headers=headers_, status_code=status.code)
                except (ClassNotFound, InstanceExists, PropertyNotFound, InvalidDateTimeFormat) as e:
                    error = e.get_HTTP()
                    return error_response(error)
        error = HydraError(code=400, title='Data is not valid')
