def func(entry):
    if isinstance(entry, FVal):
        return str(entry)
    if isinstance(entry, list):
        return [func(x) for x in entry]
    if isinstance(entry, dict | AttributeDict):
        new_dict = {}
        for k, v in entry.items():
            if isinstance(k, Asset) is True:
                k = k.identifier
            elif isinstance(k, HistoryEventType | HistoryEventSubType | EventCategory | Location | AccountingEventType) is True:
                k = func(k)
            new_dict[k] = func(v)
        return new_dict
    if isinstance(entry, HexBytes):
        return entry.hex()
    if isinstance(entry, LocationData):
        return {'time': entry.time, 'location': str(Location.deserialize_from_db(entry.location)), 'usd_value': entry.usd_value}
    if isinstance(entry, SingleDBAssetBalance):
        return {'time': entry.time, 'category': str(entry.category), 'amount': str(entry.amount), 'usd_value': str(entry.usd_value)}
    if isinstance(entry, DBAssetBalance):
        return {'time': entry.time, 'category': str(entry.category), 'asset': entry.asset.identifier, 'amount': str(entry.amount), 'usd_value': str(entry.usd_value)}
    if isinstance(entry, AddressbookEntry | AssetBalance | DefiProtocol | MakerdaoVault | XpubData | NodeName | NodeName | SingleBlockchainAccountData | SupportedBlockchain | HistoryEventType | HistoryEventSubType | EventDirection | EvmProduct | DBSettings | TxAccountingTreatment | EventCategoryDetails):
        return entry.serialize()
    if isinstance(entry, Trade | EvmTransaction | OptimismTransaction | MakerdaoVault | DSRAccountReport | Balance | AaveLendingBalance | AaveBorrowingBalance | CompoundBalance | YearnVaultEvent | YearnVaultBalance | LiquidityPool | LiquidityPoolAsset | LiquidityPoolEventsBalance | BalancerBPTEventPoolToken | BalancerEvent | BalancerPoolEventsBalance | BalancerPoolBalance | BalancerPoolTokenBalance | ManuallyTrackedBalanceWithValue | Trove | DillBalance | NFTResult | ExchangeLocationID | WeightedNode):
        return process_result(entry.serialize())
    if isinstance(entry, VersionCheckResult | DSRCurrentBalances | VaultEvent | MakerdaoVaultDetails | AaveBalances | DefiBalance | DefiProtocolBalances | YearnVaultHistory | BlockchainAccountData | CounterpartyDetails | AaveStats):
        return process_result(entry._asdict())
    if isinstance(entry, tuple):
        return list(entry)
    if isinstance(entry, Asset):
        return entry.identifier
