def func(subtype, filename, dtype=uint8, mode='r+', offset=0, shape=None, order='C'):
    import mmap
    import os.path
    try:
        mode = mode_equivalents[mode]
    except KeyError:
        if mode not in valid_filemodes:
            raise ValueError('mode must be one of %s' % (valid_filemodes + list(mode_equivalents.keys())))
    if hasattr(filename, 'read'):
        fid = filename
        own_file = False
    else:
        fid = open(filename, (mode == 'c' and 'r' or mode) + 'b')
        own_file = True
    if mode == 'w+' and shape is None:
        raise ValueError('shape must be given')
    fid.seek(0, 2)
    flen = fid.tell()
    descr = dtypedescr(dtype)
    _dbytes = descr.itemsize
    if shape is None:
        bytes = flen - offset
        if bytes % _dbytes:
            fid.close()
            raise ValueError('Size of available data is not a multiple of the data-type size.')
        size = bytes // _dbytes
        shape = (size,)
    else:
        if not isinstance(shape, tuple):
            shape = (shape,)
        size = 1
        for k in shape:
            size *= k
    bytes = long(offset + size * _dbytes)
    if mode == 'w+' or (mode == 'r+' and flen < bytes):
        fid.seek(bytes - 1, 0)
        fid.write(np.compat.asbytes('\x00'))
        fid.flush()
    if mode == 'c':
        acc = mmap.ACCESS_COPY
    elif mode == 'r':
        acc = mmap.ACCESS_READ
    else:
        acc = mmap.ACCESS_WRITE
    start = offset - offset % mmap.ALLOCATIONGRANULARITY
    bytes -= start
    offset -= start
    mm = mmap.mmap(fid.fileno(), bytes, access=acc, offset=start)
    self = ndarray.__new__(subtype, shape, dtype=descr, buffer=mm, offset=offset, order=order)
    self._mmap = mm
    self.offset = offset
    self.mode = mode
    if isinstance(filename, basestring):
        self.filename = os.path.abspath(filename)
    elif hasattr(filename, 'name') and isinstance(filename.name, basestring):
        self.filename = os.path.abspath(filename.name)
    else:
        self.filename = None
    if own_file:
        fid.close()
    return self

