    template_params = json.loads(request.form.get('templateParams') or '{}')
    if len(template_params) > 0:
        return json_error_response('SQL validation does not support template parameters', status=400)
    session = db.session()
    mydb = session.query(models.Database).filter_by(id=database_id).first()
    if not mydb:
        json_error_response('Database with id {} is missing.'.format(database_id), status=400)
    spec = mydb.db_engine_spec
    validators_by_engine = get_feature_flags().get('SQL_VALIDATORS_BY_ENGINE')
    if not validators_by_engine or spec.engine not in validators_by_engine:
        return json_error_response('no SQL validator is configured for {}'.format(spec.engine), status=400)
    validator_name = validators_by_engine[spec.engine]
    validator = get_validator_by_name(validator_name)
    if not validator:
        return json_error_response('No validator named {} found (configured for the {} engine)'.format(validator_name, spec.engine))
    try:
        timeout = config.get('SQLLAB_VALIDATION_TIMEOUT')
        timeout_msg = f'The query exceeded the {timeout} seconds timeout.'
        with utils.timeout(seconds=timeout, error_message=timeout_msg):
            errors = validator.validate(sql, schema, mydb)
        payload = json.dumps([err.to_dict() for err in errors], default=utils.pessimistic_json_iso_dttm_ser, ignore_nan=True, encoding=None)
        return json_success(payload)
    except Exception as e:
        logging.exception(e)
        msg = _(f'{validator.name} was unable to check your query.\nPlease make sure that any services it depends on are available\nException: {e}')
        return json_error_response(f'{msg}')

def func(user):
    match = USERID_RE.match(user.user_id)
    if not match:
        return None
    encoded_address = match.group(1)
    address = to_canonical_address(encoded_address)
    try:
        displayname = user.get_display_name()
        recovered = recover(data=user.user_id.encode(), signature=decode_hex(displayname))
        if not (address and recovered and (recovered == address)):
            return None
    except (DecodeError, TypeError, InvalidSignature, MatrixRequestError, json.decoder.JSONDecodeError):
        return None
    return address

def func(password, salt=None, algorithm='argon2'):
    if salt is None:
        salt = uuid.uuid4().hex
    if isinstance(salt, str):
        salt = salt.encode('utf-8')
    if isinstance(password, str):
        password = password.encode('utf-8')
    hash_func = get_utility(IPasswordHasher, name=algorithm)
    hashed_password = hash_func(password, salt)
    return '{}:{}:{}'.format(algorithm, salt.decode('utf-8'), hashed_password)

