def func(self, _address_to_room_ids):
    _msg = '_leave_unused_rooms called without account data lock'
    assert self._account_data_lock.locked(), _msg
    self._client.set_account_data('network.raiden.rooms', cast(Dict[str, Any], _address_to_room_ids))
    return
    whitelisted_hex_addresses = {to_checksum_address(address) for address in self._address_mgr.known_addresses}
    keep_rooms = set()
    for address_hex, room_ids in list(_address_to_room_ids.items()):
        if not room_ids:
            room_ids = list()
        if not isinstance(room_ids, list):
            room_ids = [room_ids]
        if address_hex not in whitelisted_hex_addresses:
            _address_to_room_ids.pop(address_hex)
            continue
        counters = [0, 0]
        new_room_ids = list()
        for room_id in room_ids:
            if room_id not in self._client.rooms:
                continue
            elif self._client.rooms[room_id].invite_only is None:
                new_room_ids.append(room_id)
            elif counters[self._client.rooms[room_id].invite_only] < 2:
                counters[self._client.rooms[room_id].invite_only] += 1
                new_room_ids.append(room_id)
            else:
                continue
        keep_rooms |= set(new_room_ids)
        if room_ids != new_room_ids:
            _address_to_room_ids[address_hex] = new_room_ids
    rooms = list(self._client.rooms.items())
    self.log.debug('Updated address room mapping', address_to_room_ids=_address_to_room_ids)
    self._client.set_account_data('network.raiden.rooms', _address_to_room_ids)
    def leave(room):
        try:
            self.log.debug('Leaving unused room', room=room)
            return room.leave()
        except KeyError:
            return True
    for room_id, room in rooms:
        if room_id in {groom.room_id for groom in self._global_rooms.values() if groom}:
            continue
        if room_id not in keep_rooms:
            greenlet = self._spawn(leave, room)
            greenlet.name = f'MatrixTransport.leave node:{pex(self._raiden_service.address)} user_id:{self._user_id}'

def func(self, job):
    qubit_set = set()
    qubit_list = []
    circuit = job.circuit
    for moment in circuit:
        for op in moment.operations:
            for qubit in op.qubits:
                if qubit not in qubit_set:
                    qubit_set.add(qubit)
                    qubit_list.append(qubit)
    moments = []
    error_number = 0
    error_sweep = Zip()
    for moment in circuit:
        moments.append(moment)
        for gate in self.depolarizing_gates:
            error_gates = []
            for q in qubit_list:
                errors = np.random.random(self.realizations) < self.p
                if any(errors):
                    key = self._parameter_name + str(error_number)
                    new_error_gate = copy.deepcopy(gate)
                    new_error_gate.half_turns = Symbol(key)
                    error_gates.append(new_error_gate.on(q))
                    error_sweep += Points(key, list(errors * 1.0))
                    error_number += 1
            if error_gates:
                moments.append(Moment(error_gates))
    sweep = job.sweep
    if error_sweep:
        sweep *= error_sweep
    return Job(Circuit(moments), sweep, job.repetitions)

def func(self, key1_key2_key3_key4):
    assert type(key1_key2_key3_key4) == tuple and len(key1_key2_key3_key4) == 4
    key1, key2, key3, key4 = key1_key2_key3_key4
    if key1 is None:
        key1 = uuid.UUID(bytes=b'\x00' * 16)
    if key2 is None:
        key2 = b'\x00' * 20
    if key3 is None:
        key3 = 0
    if key4 is None:
        key4 = uuid.UUID(bytes=b'\x00' * 16)
    assert isinstance(key1, uuid.UUID)
    assert type(key2) == bytes and len(key2) == 20
    assert type(key3) == int and key3 >= 0 and (key3 < 256)
    assert isinstance(key4, uuid.UUID)
    return key1.bytes + key2 + struct.pack('B', key3) + key4.bytes

