async def func(name, interval=typer.Option(None, '--interval', help='An interval to schedule on, specified in seconds', min=0.0001), interval_anchor=typer.Option(None, '--anchor-date', help='The anchor date for an interval schedule'), rrule_string=typer.Option(None, '--rrule', help='Deployment schedule rrule string'), cron_string=typer.Option(None, '--cron', help='Deployment schedule cron string'), cron_day_or=typer.Option(None, '--day_or', help='Control how croniter handles `day` and `day_of_week` entries'), timezone=typer.Option(None, '--timezone', help="Deployment schedule timezone string e.g. 'America/New_York'"), active=typer.Option(True, '--active', help='Whether the schedule is active. Defaults to True.'), replace=typer.Option(False, '--replace', help="Replace the deployment's current schedule(s) with this new schedule."), assume_yes=typer.Option(False, '--accept-yes', '-y', help='Accept the confirmation prompt without prompting')):
    assert_deployment_name_format(name)
    if sum((option is not None for option in [interval, rrule_string, cron_string])) != 1:
        exit_with_error('Exactly one of `--interval`, `--rrule`, or `--cron` must be provided.')
    schedule = None
    if interval_anchor and (not interval):
        exit_with_error('An anchor date can only be provided with an interval schedule')
    if interval is not None:
        if interval_anchor:
            try:
                pendulum.parse(interval_anchor)
            except ValueError:
                return exit_with_error('The anchor date must be a valid date string.')
        interval_schedule = {'interval': interval, 'anchor_date': interval_anchor, 'timezone': timezone}
        schedule = IntervalSchedule(**{k: v for k, v in interval_schedule.items() if v is not None})
    if cron_string is not None:
        cron_schedule = {'cron': cron_string, 'day_or': cron_day_or, 'timezone': timezone}
        schedule = CronSchedule(**{k: v for k, v in cron_schedule.items() if v is not None})
    if rrule_string is not None:
        if 'TZID' in rrule_string and (not timezone):
            exit_with_error("You can provide a timezone by providing a dict with a `timezone` key to the --rrule option. E.g. {'rrule': 'FREQ=MINUTELY;INTERVAL=5', 'timezone': 'America/New_York'}.\nAlternatively, you can provide a timezone by passing in a --timezone argument.")
        try:
            schedule = RRuleSchedule(**json.loads(rrule_string))
            if timezone:
                schedule.timezone = timezone
        except json.JSONDecodeError:
            schedule = RRuleSchedule(rrule=rrule_string, timezone=timezone)
    if schedule is None:
        return exit_with_success('Could not create a valid schedule from the provided options.')
    async with get_client() as client:
        try:
            deployment = await client.read_deployment_by_name(name)
        except ObjectNotFound:
            return exit_with_error(f'Deployment {name!r} not found!')
        num_schedules = len(deployment.schedules)
        noun = 'schedule' if num_schedules == 1 else 'schedules'
        if replace and num_schedules > 0:
            if not assume_yes and (not typer.confirm(f'Are you sure you want to replace {num_schedules} {noun} for {name}?')):
                return exit_with_error('Schedule replacement cancelled.')
            for existing_schedule in deployment.schedules:
                try:
                    await client.delete_deployment_schedule(deployment.id, existing_schedule.id)
                except ObjectNotFound:
                    pass
        await client.create_deployment_schedules(deployment.id, [(schedule, active)])
        if replace and num_schedules > 0:
            exit_with_success(f'Replaced existing deployment {noun} with new schedule!')
        else:
            exit_with_success('Created deployment schedule!')

def func(self, file, mode='r', *, filters=None, dereference=False, password=None, header_encryption=False, blocksize=None, mp=False):
    if mode not in ('r', 'w', 'x', 'a'):
        raise ValueError("ZipFile requires mode 'r', 'w', 'x', or 'a'")
    if mode == 'x':
        raise NotImplementedError
    self.mp = mp
    self.password_protected = password is not None
    if blocksize:
        self._block_size = blocksize
    else:
        self._block_size = get_default_blocksize()
    if isinstance(file, str):
        self._filePassed = False
        self.filename = file
        if mode == 'r':
            self.fp = open(file, 'rb')
        elif mode == 'w':
            self.fp = open(file, 'w+b')
        elif mode == 'x':
            self.fp = open(file, 'x+b')
        elif mode == 'a':
            self.fp = open(file, 'r+b')
        else:
            raise ValueError('File open error.')
        self.mode = mode
    elif isinstance(file, pathlib.Path):
        self._filePassed = False
        self.filename = str(file)
        if mode == 'r':
            self.fp = file.open(mode='rb')
        elif mode == 'w':
            self.fp = file.open(mode='w+b')
        elif mode == 'x':
            self.fp = file.open(mode='x+b')
        elif mode == 'a':
            self.fp = file.open(mode='r+b')
        else:
            raise ValueError('File open error.')
        self.mode = mode
    elif isinstance(file, multivolumefile.MultiVolume):
        self._filePassed = True
        self.fp = file
        self.filename = None
        self.mode = mode
    elif isinstance(file, io.IOBase):
        self._filePassed = True
        self.fp = file
        self.filename = getattr(file, 'name', None)
        self.mode = mode
    else:
        raise TypeError('invalid file: {}'.format(type(file)))
    self.encoded_header_mode = True
    self.header_encryption = header_encryption
    self._fileRefCnt = 1
    try:
        if mode == 'r':
            self._real_get_contents(password)
            self.fp.seek(self.afterheader)
            self.worker = Worker(self.files, self.afterheader, self.header, self.mp)
        elif mode == 'w':
            self._prepare_write(filters, password)
        elif mode == 'a':
            self._real_get_contents(password)
            self._prepare_append(filters, password)
        else:
            raise ValueError("Mode must be 'r', 'w', 'x', or 'a'")
    except Exception as e:
        self._fpclose()
        raise e
    self._dict = {}
    self.dereference = dereference
    self.reporterd = None
    self.q = queue.Queue()

def func(graph, edge_attr=None, node_attr=None, iterations=3, digest_size=16):
    def weisfeiler_lehman_step(G, labels, node_subgraph_hashes, edge_attr=None):
        new_labels = {}
        for node in G.nodes():
            label = _neighborhood_aggregate(G, node, labels, edge_attr=edge_attr)
            hashed_label = _hash_label(label, digest_size)
            new_labels[node] = hashed_label
            node_subgraph_hashes[node].append(hashed_label)
        return new_labels
    node_labels = _init_node_labels(graph, edge_attr, node_attr)
    node_subgraph_hashes = defaultdict(list)
    for _ in range(iterations):
        node_labels = weisfeiler_lehman_step(graph, node_labels, node_subgraph_hashes, edge_attr)
    return dict(node_subgraph_hashes)

