    remote_origin = get_remote_origin(local_path, verbose=workspace.verbose)
    if remote_origin is None:
        raise ConfigurationError('Remote origin is missing for git repository at %s. ' % local_path + 'Please configure before adding resource.')
    current, others = get_branch_info(local_path, workspace.verbose)
    if branch is None:
        branch = current
    if branch != current and branch not in others:
        raise ConfigurationError("Requested branch '%s' is not available for git repository at %s" % (branch, local_path))
    if is_git_dirty(local_path) and branch != current:
        click.echo('WARNING: Git repo is currently on branch %s and branch %s was requested. However, the current branch has uncommitted changes. Will skip changing the branch after adding the repo to workspace.' % (current, branch))
    else:
        switch_git_branch(local_path, branch, workspace.verbose)
    if imported:
        lineage_path = join(local_path, 'lineage.json')
        if not exists(lineage_path):
            raise ConfigurationError('--imported was specified, but missing exported lineage file %s' % lineage_path)
        if not isinstance(workspace, SnapshotWorkspaceMixin) or not workspace.supports_lineage():
            raise ConfigurationError('--imported was specified, but this workspace does not support lineage')
        with open(lineage_path, 'r') as f:
            lineage_data = json.load(f)
        if lineage_data['resource_name'] != name:
            raise ConfigurationError("Resource name in imported lineage '%s' does not match '%s'" % (lineage_data['resource_name'], name))
        cast(SnapshotWorkspaceMixin, workspace).get_lineage_store().import_lineage_file(name, lineage_data['lineages'])
    workspace_dir = get_workspace_dir(workspace)
    relative_local_path = None
    if commonpath([workspace_dir, local_path]) == workspace_dir:
        relative_local_path = get_subpath_from_absolute(workspace_dir, local_path)
    return GitRepoResource(name, role, workspace, remote_origin, relative_local_path, local_path, branch, read_only, export, imported)

