def func(num):
    s = num - 1
    t = 0
    while s % 2 == 0:
        s = s // 2
        t += 1
    for trials in range(5):
        a = random.randrange(2, num - 1)
        v = pow(a, s, num)
        if v != 1:
            i = 0
            while v != num - 1:
                if i == t - 1:
                    return False
                else:
                    i = i + 1
                    v = v ** 2 % num
    return True

def func(self, input_or_adv, label=None, unpack=True, steps=100, subsample=10, p=None):
    a = input_or_adv
    del input_or_adv
    del label
    del unpack
    if not a.has_gradient():
        return
    if a.target_class() is not None:
        logging.fatal('DeepFool is an untargeted adversarial attack.')
        return
    if p is None:
        if a._distance == MeanSquaredDistance:
            p = 2
        elif a._distance == Linfinity:
            p = np.inf
        else:
            raise NotImplementedError('Please choose a distance measure for which DeepFool is implemented or specify manually which norm to optimize.')
    if not 1 <= p <= np.inf:
        raise ValueError
    if p not in [2, np.inf]:
        raise NotImplementedError
    _label = a.original_class
    logits, _ = a.predictions(a.original_image)
    labels = np.argsort(logits)[::-1]
    if subsample:
        logging.info('Only testing the top-{} classes'.format(subsample))
        assert isinstance(subsample, int)
        labels = labels[:subsample]
    def get_residual_labels(logits):
        return [k for k in labels if logits[k] < logits[_label]]
    perturbed = a.original_image
    min_, max_ = a.bounds()
    for step in range(steps):
        logits, grad, is_adv = a.predictions_and_gradient(perturbed)
        if is_adv:
            return
        loss = -crossentropy(logits=logits, label=_label)
        residual_labels = get_residual_labels(logits)
        losses = [-crossentropy(logits=logits, label=k) for k in residual_labels]
        grads = [a.gradient(perturbed, label=k) for k in residual_labels]
        diffs = [(l - loss, g - grad) for l, g in zip(losses, grads)]
        if p == 2:
            distances = [abs(dl) / (np.linalg.norm(dg) + 1e-08) for dl, dg in diffs]
        elif p == np.inf:
            distances = [abs(dl) / (np.sum(np.abs(dg)) + 1e-08) for dl, dg in diffs]
        else:
            assert False
        optimal = np.argmin(distances)
        df, dg = diffs[optimal]
        if p == 2:
            perturbation = abs(df) / (np.linalg.norm(dg) + 1e-08) ** 2 * -dg
        elif p == np.inf:
            perturbation = abs(df) / (np.sum(np.abs(dg)) + 1e-08) * np.sign(-dg)
        else:
            assert False
        perturbed = perturbed + 1.05 * perturbation
        perturbed = np.clip(perturbed, min_, max_)
    a.predictions(perturbed)

