def func(wrapping_key, wrapped_key, backend):
    if len(wrapped_key) < 24:
        raise InvalidUnwrap('Must be at least 24 bytes')
    if len(wrapped_key) % 8 != 0:
        raise InvalidUnwrap('The wrapped key must be a multiple of 8 bytes')
    if len(wrapping_key) not in [16, 24, 32]:
        raise ValueError('The wrapping key must be a valid AES key length')
    aiv = b'\xa6\xa6\xa6\xa6\xa6\xa6\xa6\xa6'
    r = [wrapped_key[i:i + 8] for i in range(0, len(wrapped_key), 8)]
    a = r.pop(0)
    a, r = _unwrap_core(wrapping_key, a, r, backend)
    if not bytes_eq(a, aiv):
        raise InvalidUnwrap()
    return b''.join(r)

def func(self, eval_dataloader, eval_index, data, model, typ, ep, method='sum'):
    device = self.device
    model.eval()
    nb_eval_steps, nb_eval_examples = (0, 0)
    tq = tqdm(eval_dataloader, desc='Scoring:')
    all_results_sum = {}
    all_results_max = {}
    is_multifact = False
    for input_ids, input_mask, segment_ids, label_ids, unique_ids in tq:
        input_ids = input_ids.to(device)
        input_mask = input_mask.to(device)
        segment_ids = segment_ids.to(device)
        label_ids = label_ids.to(device)
        unique_ids = unique_ids.to(device)
        with torch.no_grad():
            logits = model(input_ids, segment_ids, input_mask)
        logits = logits.detach().cpu().tolist()
        label_ids = label_ids.detach().cpu().tolist()
        unique_ids = unique_ids.detach().cpu().tolist()
        nb_eval_examples += input_ids.size(0)
        nb_eval_steps += 1
        for q, scores in zip(unique_ids, logits):
            idx = eval_index[q]
            scores = softmax(scores)
            if ':' in idx:
                qid = idx.split(':')[0]
                is_multifact = True
            else:
                qid = idx
            if qid not in all_results_sum:
                all_results_sum[qid] = scores
                all_results_max[qid] = scores
            else:
                current_scores = all_results_sum[qid]
                all_results_sum[qid] = (np.array(scores) + np.array(current_scores)).tolist()
                current_scores = all_results_max[qid]
                final_scores = []
                for cscore, pscores in zip(scores, current_scores):
                    maxscore = max(cscore, pscores)
                    final_scores.append(maxscore)
                all_results_max[qid] = final_scores
    accuracy_dict = {}
    count = 0
    corrects_sum = {}
    incorrects_sum = {}
    corrects_max = {}
    incorrects_max = {}
    for qid, scores in all_results_sum.items():
        maxidx = np.argsort(scores).tolist()[-1]
        qidx = qid if not is_multifact else qid + ':0'
        if self.get_label(data, qid) == maxidx:
            count += 1
    accuracy_dict['sum_acc'] = float(count) / float(len(all_results_sum))
    count = 0
    for qid, scores in all_results_max.items():
        maxidx = np.argsort(scores).tolist()[-1]
        qidx = qid if not is_multifact else qid + ':0'
        if self.get_label(data, qid) == maxidx:
            count += 1
    accuracy_dict['max_acc'] = float(count) / float(len(all_results_max))
    acc = max(accuracy_dict['sum_acc'], accuracy_dict['max_acc'])
    if self.best_metric is None:
        self.best_metric = {}
        self.best_metric['best-acc'] = acc
    self.best_metric['%s-%d' % (typ, ep)] = accuracy_dict
    if self.best_metric['best-acc'] <= acc and typ == 'val':
        self.best_metric['best-acc'] = acc
        model_to_save = model.module if hasattr(model, 'module') else model
        output_model_file = os.path.join(self.output_dir, 'best_model.bin')
        torch.save(model_to_save.state_dict(), output_model_file)
    logger.info(json.dumps(accuracy_dict))
    return

def func(self, arrow):
    if not arrow:
        raise ValueError('Can only add arrows of length at least 1')
    if arrow in self:
        return
    if not self.graph.has_edge(arrow[0], arrow[-1]):
        self.graph.add_edge(arrow[0], arrow[-1])
    if len(arrow) >= 2:
        for idx in range(1, len(arrow)):
            fst_arrow = arrow[:idx]
            scd_arrow = arrow[idx:]
            if fst_arrow not in self:
                self.add(fst_arrow)
            if scd_arrow not in self:
                self.add(scd_arrow)
    value = self._comp(arrow)
    self._graph[arrow[0]][arrow[-1]][arrow.derive()] = value

def func(cls, arrangement_id, rest_payload, ursula, alice_address):
    payload_splitter = BytestringSplitter(Signature) + key_splitter
    payload_elements = payload_splitter(rest_payload, msgpack_remainder=True)
    signature, bob_verifying_key, (tasks_bytes, blockhash) = payload_elements
    ursula_identity_evidence = b''
    if ursula._stamp_has_valid_signature_by_worker():
        ursula_identity_evidence = ursula.decentralized_identity_evidence
    tasks = []
    for task_bytes in tasks_bytes:
        task = cls.PRETask.from_bytes(task_bytes)
        tasks.append(task)
        specification = task.get_specification(ursula.stamp, alice_address, blockhash, ursula_identity_evidence)
        if not task.signature.verify(specification, bob_verifying_key):
            raise InvalidSignature()
    receipt_bytes = b'wo:' + bytes(ursula.stamp) + keccak_digest(*[bytes(task.capsule) for task in tasks])
    if not signature.verify(receipt_bytes, bob_verifying_key):
        raise InvalidSignature()
    bob = Bob.from_public_keys(verifying_key=bob_verifying_key)
    return cls(bob=bob, ursula=ursula, arrangement_id=arrangement_id, tasks=tasks, alice_address=alice_address, blockhash=blockhash, receipt_signature=signature)

