async def func(self, engine, message, cache=None, language=None, options=None):
    provider = self.providers[engine]
    msg_hash = hashlib.sha1(bytes(message, 'utf-8')).hexdigest()
    use_cache = cache if cache is not None else self.use_cache
    language = language or provider.default_language
    if language is None or language not in provider.supported_languages:
        raise HomeAssistantError('Not supported language {0}'.format(language))
    if provider.default_options and options:
        merged_options = provider.default_options.copy()
        merged_options.update(options)
        options = merged_options
    options = options or provider.default_options
    if options is not None:
        invalid_opts = [opt_name for opt_name in options.keys() if opt_name not in (provider.supported_options or [])]
        if invalid_opts:
            raise HomeAssistantError('Invalid options found: {}'.format(invalid_opts))
        options_key = ctypes.c_size_t(hash(frozenset(options))).value
    else:
        options_key = '-'
    key = KEY_PATTERN.format(msg_hash, language, options_key, engine).lower()
    if key in self.mem_cache:
        filename = self.mem_cache[key][MEM_CACHE_FILENAME]
    elif use_cache and key in self.file_cache:
        filename = self.file_cache[key]
        self.hass.async_add_job(self.async_file_to_mem(key))
    else:
        filename = await self.async_get_tts_audio(engine, key, message, use_cache, language, options)
    return '{}/api/tts_proxy/{}'.format(self.hass.config.api.base_url, filename)

