def func(pfx_file_bytes, password):
    private_key, x509_cert, additional_certs = crypto_x509_backend.load_key_and_certificates_from_pkcs12(data=pfx_file_bytes, password=password.encode() if password is not None else None)
    assert x509_cert is not None
    subject_alt_name_ext = x509_cert.extensions.get_extension_for_class(cryptography.x509.extensions.SubjectAlternativeName)
    try:
        results = [x.value for x in subject_alt_name_ext.value._general_names if hasattr(x, 'type_id') and x.type_id == constants.SII_CERT_TITULAR_RUT_OID]
    except AttributeError as exc:
        raise Exception(f'Malformed certificate extension: {subject_alt_name_ext.oid}') from exc
    if not results:
        raise Exception('Certificate has no RUT information')
    elif len(results) > 1:
        raise Exception(f'len(results) == {len(results)}')
    subject_rut_raw = results[0]
    subject_rut = re.sub('[^0-9-]', '', subject_rut_raw.decode('utf-8'))
    return Rut(subject_rut)

