def func(expr, new_stmts):
    if is_simple(expr):
        return expr
    if isinstance(expr, ast.BoolOp):
        expr.values = [func(v, new_stmts) for v in expr.values]
        return expr
    elif isinstance(expr, ast.BinOp):
        expr.left = func(expr.left, new_stmts)
        expr.right = func(expr.right, new_stmts)
        return maybe_store(expr, new_stmts)
    elif isinstance(expr, ast.UnaryOp):
        expr.operand = func(expr.operand, new_stmts)
        return maybe_store(expr, new_stmts)
    elif isinstance(expr, ast.Lambda):
        res_body = []
        res_expr = func(expr.body, res_body)
        res_body.append(ast.Return(value=res_expr))
        args = explode_arguments(expr.args, new_stmts)
        res_load, res_store = gensym()
        define = ast.FunctionDef(name=res_store.id, args=args, body=res_body, decorator_list=[], returns=None)
        new_stmts.append(define)
        return res_load
    elif isinstance(expr, ast.IfExp):
        res_load, res_store = gensym()
        if_body = []
        expr.body = func(expr.body, if_body)
        if_body.append(ast.Assign(targets=[res_store], value=expr.body))
        else_body = []
        expr.orelse = func(expr.orelse, else_body)
        else_body.append(ast.Assign(targets=[c.deepcopy(res_store)], value=expr.orelse))
        new_stmts.append(ast.If(test=expr.test, body=if_body, orelse=else_body))
        return res_load
    elif isinstance(expr, ast.Dict):
        return explode_dict(expr, new_stmts)
    elif isinstance(expr, ast.Set):
        expr.elts = [func(elt, new_stmts) for elt in expr.elts]
        return expr
    elif isinstance(expr, (ast.ListComp, ast.GeneratorExp)):
        return explode_list_comp(expr, new_stmts, ast.List(elts=[], ctx=ast.Load()), 'append')
    elif isinstance(expr, ast.SetComp):
        return explode_list_comp(expr, new_stmts, ast.Set(elts=[], ctx=ast.Load()), 'add')
    elif isinstance(expr, ast.DictComp):
        return '{' + '{}: {} {}'.format(expr_to_str(expr.key), expr_to_str(expr.value), ' '.join(map(comprehension_to_str, expr.generators))) + '}'
    elif isinstance(expr, ast.Starred):
        expr.value = func(expr.value, new_stmts)
        return expr
    elif isinstance(expr, (ast.Yield, ast.YieldFrom, ast.Await, ast.FormattedValue)):
        expr.value = func(expr.value, new_stmts)
        return expr
    elif isinstance(expr, ast.Compare):
        expr.left = func(expr.left, new_stmts)
        expr.comparators = [func(comp, new_stmts) for comp in expr.comparators]
        return maybe_store(expr, new_stmts)
    elif isinstance(expr, ast.Call):
        expr.func = func(expr.func, new_stmts)
        expr.args = [func(arg, new_stmts) for arg in expr.args]
        for keyword in expr.keywords:
            keyword.value = func(keyword.value, new_stmts)
        return maybe_store(expr, new_stmts)
    elif isinstance(expr, (ast.Num, ast.Bytes, ast.Str, ast.NameConstant, ast.Constant, ast.Ellipsis, ast.Name)):
        assert False
    elif isinstance(expr, ast.JoinedStr):
        expr.values = [func(val, new_stmts) for val in expr.values]
        return expr
    elif isinstance(expr, ast.Attribute):
        expr.value = func(expr.value, new_stmts)
        return maybe_store(expr, new_stmts)
    elif isinstance(expr, ast.Subscript):
        expr.value = func(expr.value, new_stmts)
        expr.slice = explode_slice(expr.slice, new_stmts)
        return maybe_store(expr, new_stmts)
    elif isinstance(expr, (ast.List, ast.Tuple)):
        expr.elts = [func(elt, new_stmts) for elt in expr.elts]
        return expr
    else:
        assert False

