            matcher_instance = matcher(settings)
            matchers_list.append((matcher_instance, settings.matchers[matcher_name]))
    return sorted(matchers_list, key=itemgetter(1))

def func(obj, encode_json=False, skip_none_field=False):
    if _is_declared_instance(obj):
        result = []
        for field in fields(obj):
            if field.ignore_serialize:
                continue
            field_value = obj.__dict__.get(field.name, MISSING)
            if field_value is MISSING:
                field_value = field.make_default()
                if field_value is MISSING:
                    if not field.required:
                        field_value = None
                    else:
                        raise AttributeError(f'field {field.name} is required.')
            if skip_none_field and field_value is None:
                continue
            value = func(field_value, encode_json=encode_json, skip_none_field=skip_none_field)
            result.append((field.field_name, value))
        return _encode_overrides(dict(result), None, encode_json=encode_json)
    elif isinstance(obj, Mapping):
        return dict(((func(k, encode_json=encode_json), func(v, encode_json=encode_json)) for k, v in obj.items()))
    elif isinstance(obj, Collection) and (not isinstance(obj, str)):
        return list((func(v, encode_json=encode_json) for v in obj))
    else:
        return copy.deepcopy(obj)

async def func(sources, line_length, write_back, fast, loop, executor):
    tasks = {src: loop.run_in_executor(executor, format_file_in_place, src, line_length, fast, write_back) for src in sources}
    await asyncio.wait(tasks.values())
    cancelled = []
    report = Report()
    for src, task in tasks.items():
        if not task.done():
            report.failed(src, 'timed out, cancelling')
            task.cancel()
            cancelled.append(task)
        elif task.exception():
            report.failed(src, str(task.exception()))
        else:
            report.done(src, task.result())
    if cancelled:
        await asyncio.wait(cancelled, timeout=2)
    out('All done! ✨ 🍰 ✨')
    click.echo(str(report))
    return report.return_code

