        if hdrs.AUTHORIZATION in request.headers and await async_validate_auth_header(request, api_password if legacy_auth else None):
            authenticated = True
        elif legacy_auth and HTTP_HEADER_HA_AUTH in request.headers and hmac.compare_digest(api_password.encode('utf-8'), request.headers[HTTP_HEADER_HA_AUTH].encode('utf-8')):
            authenticated = True
        elif legacy_auth and DATA_API_PASSWORD in request.query and hmac.compare_digest(api_password.encode('utf-8'), request.query[DATA_API_PASSWORD].encode('utf-8')):
            authenticated = True
        elif _is_trusted_ip(request, trusted_networks):
            authenticated = True
        elif not use_auth and api_password is None:
            authenticated = True
        request[KEY_AUTHENTICATED] = authenticated
        return await handler(request)
    async def auth_startup(app):
        app.middlewares.append(auth_middleware)
    app.on_startup.append(auth_startup)

async def func(self, token):
    try:
        unverif_claims = jwt.decode(token, verify=False)
    except jwt.InvalidTokenError:
        return None
    refresh_token = await self.async_get_refresh_token(unverif_claims.get('iss'))
    if refresh_token is None:
        jwt_key = ''
        issuer = ''
    else:
        jwt_key = refresh_token.jwt_key
        issuer = refresh_token.id
    try:
        jwt.decode(token, jwt_key, leeway=10, issuer=issuer, algorithms=['HS256'])
    except jwt.InvalidTokenError:
        return None
    if not refresh_token.user.is_active:
        return None
    return refresh_token

def func(default_urlresolver):
    js_var_name = getattr(settings, 'JS_REVERSE_JS_VAR_NAME', JS_VAR_NAME)
    if not JS_IDENTIFIER_RE.match(js_var_name.upper()):
        raise ImproperlyConfigured('JS_REVERSE_JS_VAR_NAME setting "%s" is not a valid javascript identifier.' % js_var_name)
    js_global_object_name = getattr(settings, 'JS_REVERSE_JS_GLOBAL_OBJECT_NAME', JS_GLOBAL_OBJECT_NAME)
    if not JS_IDENTIFIER_RE.match(js_global_object_name.upper()):
        raise ImproperlyConfigured('JS_REVERSE_JS_GLOBAL_OBJECT_NAME setting "%s" is not a valid javascript identifier.' % js_global_object_name)
    minfiy = getattr(settings, 'JS_REVERSE_JS_MINIFY', JS_MINIFY)
    if not isinstance(minfiy, bool):
        raise ImproperlyConfigured('JS_REVERSE_JS_MINIFY setting "%s" is not a valid. Needs to be set to True or False.' % minfiy)
    script_prefix_via_config = getattr(settings, 'JS_REVERSE_SCRIPT_PREFIX', None)
    if script_prefix_via_config:
        script_prefix = script_prefix_via_config
        if not script_prefix.endswith('/'):
            script_prefix = '{0}/'.format(script_prefix)
    else:
        script_prefix = urlresolvers.get_script_prefix()
    data = generate_json(default_urlresolver, script_prefix)
    js_content = loader.render_to_string('django_js_reverse/urls_js.tpl', {'data': _safe_json(data), 'js_name': '.'.join([js_global_object_name, js_var_name])})
    if minfiy:
        js_content = rjsmin.jsmin(js_content)
    return js_content

def func(self):
    if not request.is_json:
        return self.response_400(message='Request payload is not JSON')
    try:
        login_payload = login_post.load(request.json)
    except ValidationError as error:
        return self.response_400(message=error.messages)
    user = None
    if login_payload['provider'] == API_SECURITY_PROVIDER_DB:
        user = self.appbuilder.sm.auth_user_db(login_payload['username'], login_payload['password'])
    elif login_payload['provider'] == API_SECURITY_PROVIDER_LDAP:
        user = self.appbuilder.sm.auth_user_ldap(login_payload['username'], login_payload['password'])
    if not user:
        return self.response_401()
    resp = dict()
    resp[API_SECURITY_ACCESS_TOKEN_KEY] = create_access_token(identity=user.id, fresh=True)
    if 'refresh' in login_payload:
        login_payload['refresh'] = create_refresh_token(identity=user.id)
    return self.response(200, **resp)

def func(vyper_module):
    allocator = SimpleStorageAllocator()
    ret = {}
    for node in vyper_module.get_children(vy_ast.FunctionDef):
        type_ = node._metadata['type']
        if type_.nonreentrant is None:
            continue
        variable_name = f'nonreentrant.{type_.nonreentrant}'
        if variable_name in ret:
            _slot = ret[variable_name]['slot']
            type_.set_reentrancy_key_position(StorageSlot(_slot))
            continue
        slot = allocator.allocate_slot(1, variable_name)
        type_.set_reentrancy_key_position(StorageSlot(slot))
        ret[variable_name] = {'type': 'nonreentrant lock', 'slot': slot}
    for node in vyper_module.get_children(vy_ast.VariableDecl):
        if node.is_constant or node.is_immutable:
            continue
        varinfo = node.target._metadata['varinfo']
        type_ = varinfo.typ
        n_slots = type_.storage_size_in_words
        slot = allocator.allocate_slot(n_slots, node.target.id)
        varinfo.set_position(StorageSlot(slot))
        ret[node.target.id] = {'type': str(type_), 'slot': slot}
    return ret

def func(self):
    rem = 4 + self._pktlen + self._recv_macsize - self._recv_blocksize
    if len(self._inpbuf) < rem:
        return False
    rest = self._inpbuf[:rem - self._recv_macsize]
    seq = self._recv_seq
    if self._recv_mode in ('chacha', 'gcm'):
        packet = self._packet + rest
        mac = self._inpbuf[rem - self._recv_macsize:rem]
        hdr = packet[:4]
        packet = packet[4:]
        if self._recv_mode == 'chacha':
            nonce = UInt64(seq)
            packet = self._recv_cipher.verify_and_decrypt(hdr, packet, nonce, mac)
        else:
            packet = self._recv_cipher.verify_and_decrypt(hdr, packet, mac)
        if not packet:
            raise DisconnectError(DISC_MAC_ERROR, 'MAC verification failed')
    elif self._recv_mode == 'etm':
        packet = self._packet + rest
        mac = self._inpbuf[rem - self._recv_macsize:rem]
        if not self._recv_mac.verify(seq, packet, mac):
            raise DisconnectError(DISC_MAC_ERROR, 'MAC verification failed')
        packet = self._recv_cipher.decrypt(packet[4:])
    else:
        if self._recv_cipher:
            rest = self._recv_cipher.decrypt(rest)
        packet = self._packet + rest
        mac = self._inpbuf[rem - self._recv_macsize:rem]
        if self._recv_mac:
            if not self._recv_mac.verify(seq, packet, mac):
                raise DisconnectError(DISC_MAC_ERROR, 'MAC verification failed')
        packet = packet[4:]
    self._inpbuf = self._inpbuf[rem:]
    self._packet = b''
    payload = packet[1:-packet[0]]
    if self._decompressor and (self._auth_complete or not self._decompress_after_auth):
        payload = self._decompressor.decompress(payload)
    try:
        packet = SSHPacket(payload)
        pkttype = packet.get_byte()
        if self._kex and MSG_KEX_FIRST <= pkttype <= MSG_KEX_LAST:
            if self._ignore_first_kex:
                self._ignore_first_kex = False
                processed = True
            else:
                processed = self._kex.process_packet(pkttype, seq, packet)
        elif self._auth and MSG_USERAUTH_FIRST <= pkttype <= MSG_USERAUTH_LAST:
            processed = self._auth.process_packet(pkttype, seq, packet)
        elif pkttype > MSG_USERAUTH_LAST and (not self._auth_complete):
            raise DisconnectError(DISC_PROTOCOL_ERROR, 'Invalid request received before authentication was complete')
        else:
            processed = self.process_packet(pkttype, seq, packet, pkttype not in self._excluded_recv_pkttypes)
    except PacketDecodeError as exc:
        raise DisconnectError(DISC_PROTOCOL_ERROR, str(exc)) from None
    if not processed:
        self.logger.debug1('Unknown packet type %d received', pkttype)
        self.send_packet(MSG_UNIMPLEMENTED, UInt32(seq))
    if self._transport:
        self._recv_seq = seq + 1 & 4294967295
        self._recv_handler = self._recv_pkthdr
    return True
